269	// diffRows counts the lines that read as part of a diff.
270	func diffRows(lines []string) int {
271		n := 0
272		for _, l := range lines {
273			if strings.HasPrefix(l, "+") || strings.HasPrefix(l, "-") || strings.HasPrefix(l, "  @@") {
274				n++
275			}
276		}
277		return n
278	}
