280	// indexOfBlock is where block starts in lines, or -1.
281	func indexOfBlock(lines, block []string) int {
282		for i := 0; i+len(block) <= len(lines); i++ {
283			if slices.Equal(lines[i:i+len(block)], block) {
284				return i
285			}
286		}
287		return -1
288	}
