69	// ── changeLines: the display form of a patch.Diff ────────────────────────────
70	
71	func TestChangeLines(t *testing.T) {
72		tests := []struct {
73			name string
74			diff string
75			want []string
76		}{
77			{"no diff", "", nil},
78			{"only the headers", "--- f\n+++ f\n", nil},
79			{"the two header lines are dropped and the hunk marker is indented",
80				"--- Dockerfile\n+++ Dockerfile\n@@ line 2 @@\n-RUN a\n+RUN b\n",
81				[]string{"  @@ line 2 @@", "-RUN a", "+RUN b"}},
82			{"several hunks, in order",
83				"--- f\n+++ f\n@@ line 2 @@\n-a\n+b\n@@ line 9 @@\n+c\n",
84				[]string{"  @@ line 2 @@", "-a", "+b", "  @@ line 9 @@", "+c"}},
85			// A removed line "-- x" reads "--- x" and an added "++ y" reads "+++ y":
86			// only the first two lines of the diff are headers, so filtering on the
87			// prefix would silently eat real changes.
88			{"a changed line that looks like a header is kept",
89				"--- f\n+++ f\n@@ line 1 @@\n--- x\n+++ y\n",
90				[]string{"  @@ line 1 @@", "--- x", "+++ y"}},
91			{"an added empty line", "--- f\n+++ f\n@@ line 3 @@\n+\n", []string{"  @@ line 3 @@", "+"}},
92			{"no trailing empty line", "--- f\n+++ f\n@@ line 1 @@\n+a\n", []string{"  @@ line 1 @@", "+a"}},
93			{"an escape sequence is removed whole",
94				"--- f\n+++ f\n@@ line 1 @@\n+a\x1b[31mb\x1b[0m\n-c\x1b]0;title\x07d\n",
95				[]string{"  @@ line 1 @@", "+ab", "-cd"}},
96			{"a carriage return is dropped", "--- f\n+++ f\n@@ line 1 @@\n+a\r\n", []string{"  @@ line 1 @@", "+a"}},
97			{"a tab becomes four spaces", "--- f\n+++ f\n@@ line 1 @@\n+\ta\n", []string{"  @@ line 1 @@", "+    a"}},
98		}
99		for _, tt := range tests {
100			t.Run(tt.name, func(t *testing.T) {
101				got := changeLines(tt.diff)
102				if len(got) == 0 && len(tt.want) == 0 {
103					return
104				}
105				if !slices.Equal(got, tt.want) {
106					t.Errorf("changeLines(%q)\n got: %q\nwant: %q", tt.diff, got, tt.want)
107				}
108			})
109		}
110	}
