140	func TestEveryRuleYieldsAFormattedChange(t *testing.T) {
141		for _, fx := range changeFixtures(t) {
142			t.Run(fx.id, func(t *testing.T) {
143				rule := ruleOf(t, fx)
144				original := []byte(fx.files[fx.edited])
145	
146				change, declined, err := misconfigChangeOf(rule, fx.edited, original, fx.finding)
147				if err != nil || declined != "" {
148					t.Fatalf("declined %q, error %v", declined, err)
149				}
150				if change.File != fx.edited {
151					t.Errorf("File = %q, want %q", change.File, fx.edited)
152				}
153				if len(change.Lines) == 0 {
154					t.Fatal("no line")
155				}
156				for _, l := range change.Lines {
157					if !changeLineIsFormatted(l) {
158						t.Errorf("line %q starts with neither +, - nor two spaces", l)
159					}
160					if l == "--- "+fx.edited || l == "+++ "+fx.edited {
161						t.Errorf("the diff header %q is in the lines", l)
162					}
163					if strings.ContainsAny(l, "\x1b\r\x07") {
164						t.Errorf("line %q holds a control character", l)
165					}
166				}
167				if !strings.HasPrefix(change.Lines[0], "  @@ line ") || !strings.HasSuffix(change.Lines[0], " @@") {
168					t.Errorf("the first line is %q, want an indented hunk marker", change.Lines[0])
169				}
170	
171				// The bytes ctrl+o writes are the catalog's own rewrite, and the lines
172				// are the display form of its own diff: nothing else feeds them.
173				edits, _ := rule.Fix(original, fx.finding)
174				want, err := patch.Rewrite(original, edits)
175				if err != nil {
176					t.Fatal(err)
177				}
178				if !bytes.Equal(change.Updated, want) {
179					t.Errorf("Updated differs from patch.Rewrite:\n got: %q\nwant: %q", change.Updated, want)
180				}
181				diff, err := patch.Diff(fx.edited, original, edits)
182				if err != nil {
183					t.Fatal(err)
184				}
185				if !slices.Equal(change.Lines, changeLines(diff)) {
186					t.Errorf("Lines are not changeLines(patch.Diff):\n got: %q\nwant: %q", change.Lines, changeLines(diff))
187				}
188				if got, want := change.Scope, rule.ScopeOf(want, edits); got.Line != want.Line || got.EndLine != want.EndLine || !slices.Equal(got.Rules, want.Rules) {
189					t.Errorf("Scope = %+v, want %+v", got, want)
190				}
191			})
192		}
193	}
