292	// the bytes on disk are the bytes the preview was computed with.
293	func TestTheModalShowsExactlyThePreviewLinesAndTheFileWrittenIsUpdated(t *testing.T) {
294		for _, fx := range changeFixtures(t) {
295			t.Run(fx.id, func(t *testing.T) {
296				dir := fixtureOnDisk(t, fx)
297				m := changeModel(t, dir, fx.finding, time.Time{})
298	
299				m, msg := previewed(t, m)
300				if m.confirmModal == nil {
301					t.Fatalf("no confirmation opened; footer: %q", m.footer.Text())
302				}
303				if len(msg.Lines) == 0 {
304					t.Fatal("the preparation produced no preview line")
305				}
306	
307				rows := modalLines(m)
308				at := indexOfBlock(rows, msg.Lines)
309				if at < 0 {
310					t.Fatalf("the modal does not hold the preview lines:\n%q\nmodal:\n%s", msg.Lines, strings.Join(rows, "\n"))
311				}
312				if got, want := diffRows(rows), len(msg.Lines); got != want {
313					t.Errorf("the modal has %d diff rows, the preview %d: something else is shown as a change", got, want)
314				}
315				// The file and its git advice follow the lines, as before (modalLines
316				// leaves the blank rows out).
317				tail := rows[at+len(msg.Lines):]
318				if len(tail) == 0 || !strings.HasPrefix(tail[0], fx.edited+": ") {
319					t.Errorf("after the lines, the modal reads %q; want %q", tail, fx.edited+": <git advice>")
320				}
321				// The text handed to the modal is the body of the preparation.
322				if want := misconfigConfirmationText(msg.File, msg.Body); !strings.Contains(want, strings.Join(msg.Lines, "\n")) {
323					t.Errorf("the confirmation text does not hold the lines joined by newlines:\n%s", want)
324				}
325				if got := readTree(t, dir, fx.edited); got != fx.files[fx.edited] {
326					t.Fatalf("the file was written before the answer:\n%s", got)
327				}
328	
329				// Yes: the write is the one the modal was about.
330				m, cmd := step(t, m, sharedcomponents.ConfirmModalYesMsg{})
331				written, ok := run(t, cmd).(MisconfigFixWrittenMsg)
332				if !ok || written.Err != nil {
333					t.Fatalf("the write failed: %+v", written)
334				}
335				_ = feed(t, m, written)
336				if got := readTree(t, dir, fx.edited); got != string(msg.File.Updated) {
337					t.Errorf("the file on disk is not Updated:\n got: %q\nwant: %q", got, msg.File.Updated)
338				}
339				// And it is what the catalog's rewrite gives, computed here on its own.
340				edits, _ := ruleOf(t, fx).Fix([]byte(fx.files[fx.edited]), fx.finding)
341				want, err := patch.Rewrite([]byte(fx.files[fx.edited]), edits)
342				if err != nil || readTree(t, dir, fx.edited) != string(want) {
343					t.Errorf("the file on disk is not patch.Rewrite of the original (err %v)", err)
344				}
345			})
346		}
