389		if m.confirmModal == nil || msg.Err != nil {
390			t.Fatalf("no confirmation: %v", msg.Err)
391		}
392		if len(msg.Lines) == 0 {
393			t.Fatal("no preview line")
394		}
395		joined := strings.Join(msg.Lines, "\n")
396		for _, bad := range []string{"\x1b", "\x07", "pwned"} {
397			if strings.Contains(joined, bad) {
398				t.Errorf("the preview lines hold %q: %q", bad, joined)
399			}
400		}
401		if !strings.Contains(joined, "red") {
402			t.Errorf("the visible text of the line was lost: %q", joined)
403		}
404		text := misconfigConfirmationText(msg.File, msg.Body)
405		for _, bad := range []string{"\x1b", "\x07", "pwned"} {
406			if strings.Contains(text, bad) {
407				t.Errorf("the confirmation text holds %q:\n%q", bad, text)
408			}
409		}
410		// What the modal renders adds styling of its own, but never an OSC or a bell.
411		view := m.confirmModal.View()
412		if strings.Contains(view, "\x1b]") || strings.Contains(view, "\x07") {
413			t.Errorf("the rendered modal holds an OSC or a bell: %q", view)
414		}
415		if !strings.Contains(string(msg.File.Updated), hostile) {
416			t.Error("Updated lost the raw bytes of the file: the fix must edit the file, not a sanitized copy")
417		}
418	}
