442	
443	func TestPreviewFailureNamesTheFileAndNeverTheError(t *testing.T) {
444		const rel = "deploy/app.yaml"
445		secret := "open /home/someone/private/path: errno 13 raw detail"
446		tests := []struct {
447			name string
448			err  error
449		}{
450			{"not found", &fs.PathError{Op: "open", Path: "/abs/" + rel, Err: fs.ErrNotExist}},
451			{"permission", &fs.PathError{Op: "open", Path: "/abs/" + rel, Err: fs.ErrPermission}},
452			{"anything else", errors.New(secret)},
453		}
454		seen := map[string]string{}
455		for _, tt := range tests {
456			t.Run(tt.name, func(t *testing.T) {
457				got := previewFailure(rel, tt.err)
458				if got == "" {
459					t.Fatal("empty reason")
460				}
461				if strings.Contains(got, "\n") || strings.Contains(got, "/abs/") || strings.Contains(got, "errno") || strings.Contains(got, "private") {
462					t.Errorf("the reason shows the error: %q", got)
463				}
464				if prev, dup := seen[got]; dup {
465					t.Errorf("%q is also the reason for %s", got, prev)
466				}
467				seen[got] = tt.name
468			})
469		}
470		if got := previewFailure(rel, tests[1].err); got != rel+" cannot be read" {
471			t.Errorf("permission: %q, want %q", got, rel+" cannot be read")
472		}
473		if got := previewFailure(rel, tests[0].err); !strings.Contains(got, rel) {
474			t.Errorf("not found: %q does not name the file", got)
475		}
476		if got := previewFailure(rel, errors.New(secret)); got != "the fix could not be computed — check logs" {
477			t.Errorf("other: %q", got)
478		}
479		// A wrapped error is still classified.
480		wrapped := errors.Join(errors.New("context"), &fs.PathError{Op: "stat", Path: rel, Err: fs.ErrPermission})
481		if got := previewFailure(rel, wrapped); got != rel+" cannot be read" {
482			t.Errorf("wrapped permission: %q", got)
483		}
484	}
