138	// writeTree writes files under dir and gives each the modification time at, so a
139	// test never depends on the clock of the machine running it.
140	func writeTree(t *testing.T, dir string, files map[string]string, at time.Time) {
141		t.Helper()
142		for name, content := range files {
143			path := filepath.Join(dir, filepath.FromSlash(name))
144			if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
145				t.Fatal(err)
146			}
147			if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
148				t.Fatal(err)
149			}
150			touch(t, path, at)
151		}
152	}
153	
154	// touch sets the modification time of path (following a link).
155	func touch(t *testing.T, path string, at time.Time) {
156		t.Helper()
157		if err := os.Chtimes(path, at, at); err != nil {
158			t.Fatal(err)
159		}
160	}
