162	// readTree reads the file name under dir.
163	func readTree(t *testing.T, dir, name string) string {
164		t.Helper()
165		b, err := os.ReadFile(filepath.Join(dir, filepath.FromSlash(name)))
166		if err != nil {
167			t.Fatal(err)
168		}
169		return string(b)
170	}
