161	// Msgs executes cmd and returns every message it produced, flattening the
162	// tea.Batch and tea.Sequence trees. A nil command, or one returning nil, yields
163	// no messages.
164	//
165	// The command runs synchronously on the calling goroutine. Do not pass a command
166	// that sleeps or performs I/O — tea.Tick blocks for its whole duration, and the
167	// Docker runners shell out. Assert on the command's identity or on model state
168	// instead for those.
169	//
170	// A tea.Tick starts counting when the command is built, not when it runs, so a
171	// timer shortened with FastTimers must be shortened before the Update that
172	// builds the command: afterwards the full duration is already armed and Msgs
173	// sleeps for what is left of it.
174	func Msgs(cmd tea.Cmd) []tea.Msg {
175		if cmd == nil {
176			return nil
177		}
178		msg := cmd()
179		if msg == nil {
180			return nil
181		}
182		if batch, ok := msg.(tea.BatchMsg); ok {
183			var out []tea.Msg
184			for _, c := range batch {
185				out = append(out, Msgs(c)...)
186			}
187			return out
188		}
189		if seq, ok := sequenced(msg); ok {
190			var out []tea.Msg
191			for _, c := range seq {
192				out = append(out, Msgs(c)...)
193			}
194			return out
195		}
196		return []tea.Msg{msg}
197	}
198	
199	// sequenced reports whether msg is what tea.Sequence returns, and unpacks the
200	// commands it holds.
201	//
202	// tea.Batch answers with the exported tea.BatchMsg, but the equivalent for
203	// tea.Sequence is unexported — the runtime is its only intended reader, and it
204	// runs the commands one after another rather than concurrently. Its underlying
205	// type is []tea.Cmd, so reflection recovers them without depending on the name.
206	// Order is preserved, which is the whole point of a sequence: a view that emits
207	// "scan starting" before the scan itself relies on the first message arriving
208	// first.
209	func sequenced(msg tea.Msg) ([]tea.Cmd, bool) {
210		value := reflect.ValueOf(msg)
211		if value.Kind() != reflect.Slice || value.Type().Elem() != reflect.TypeFor[tea.Cmd]() {
212			return nil, false
213		}
214		// The element type was just checked, so every assertion below holds; a nil
215		// entry comes back as a nil tea.Cmd, which Msgs already ignores.
216		cmds := make([]tea.Cmd, 0, value.Len())
217		for i := range value.Len() {
218			cmds = append(cmds, value.Index(i).Interface().(tea.Cmd))
219		}
220		return cmds, true
221	}
222	
223	// Msg executes cmd and returns the single message it produced, or nil.
224	// It is the common case of Msgs for commands that emit exactly one message.
225	func Msg(cmd tea.Cmd) tea.Msg {
226		msgs := Msgs(cmd)
227		if len(msgs) == 0 {
228			return nil
229		}
230		return msgs[0]
231	}
232	
233	// MsgOf reports whether cmd produced a message of type T, returning the first
234	// such message. It searches through batched commands.
235	func MsgOf[T tea.Msg](cmd tea.Cmd) (T, bool) {
236		for _, m := range Msgs(cmd) {
237			if v, ok := m.(T); ok {
238				return v, true
239			}
240		}
241		var zero T
242		return zero, false
243	}
