func TestAFixThatClearsTheFindingClosesTheDetailWithItsReason(t *testing.T) {
	m, dir := fixDetail(t)
	m = writeFix(t, m, dir)
	m = feed(t, m, MisconfigVerifiedMsg{
		Target: dir, Rule: "AVD-DS-0002", File: "Dockerfile", Cleared: true, Result: resultOn(dir),
	})

