func TestAHostileFileNeverReachesTheSection(t *testing.T) {
	const hostile = "\x1b]0;pwned\x07\x1b[31mred\x1b[0m"
	src := "FROM debian:12\nRUN apt-get install -y curl # " + hostile + "\n"
