// ── What DevDesk cannot write: no invented diff ──────────────────────────────

func versionedCVE(version, fixedIn string) scan.Finding {
	return scan.Finding{
		ID: "CVE-2026-4242", Title: "A flaw in libfoo", Severity: scan.SeverityHigh, Source: "trivy",
