	}
}

func TestWhatDevDeskCannotWriteSaysNoneAndShowsNoDiff(t *testing.T) {
	tests := []struct {
		name   string
		f      scan.Finding
		target string
		kind   scan.TargetType
	}{
		{"a CVE with no fixed version", findingFixtures()[1], detailsTarget, scan.TargetDirectory},
