// left and the spaces on the right gone. A marker of a hunk keeps its two spaces.
func textLines(m Model) []string {
	lines := plainLines(m)
	for i, l := range lines {
		lines[i] = strings.TrimRight(strings.TrimPrefix(l, " "), " ")
	}
	return lines
