	t := &testing.T{}
	_ = t
	fx := benchFixture(b)
	dir := b.TempDir()
	writeTree(b, dir, fx.files, scannedAtFixed.Add(-time.Hour))
	b.ReportAllocs()
	for b.Loop() {
		if msg := computeMisconfigFix(dir, fx.finding, scannedAtFixed); msg.Err != nil {
			b.Fatal(msg.Err)
		}
	}
}

