SP=/tmp/claude-1000/-home-anthoni-projects-workspace-entire-anthnel-devdesk/240cfea5-e409-4e25-85ee-ef1052c5a295/scratchpad/ref/internal/ui/security; cd $SP && cat > details_change.go <<'EOF'
package security

import (
	"errors"
	"log"
	"strings"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/scan"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

type previewState int

const (
	previewPending previewState = iota
	previewReady
	previewDeclined
	previewExpired
	previewFailed
)

type ChangePreviewMsg struct {
	Seq      int
	Target   string
	Prepared MisconfigFixPreparedMsg
}

type changePreview struct {
	Seq      int
	Target   string
	Finding  scan.Finding
	State    previewState
	Prepared MisconfigFixPreparedMsg
	Failure  string
}

const maxChangeRows = 8

func (m *Model) startChangePreview() tea.Cmd {
	m.changePreview = changePreview{}
	if m.selectedFinding == nil || m.result == nil || !m.targetOnDisk() {
		return nil
	}
	f := *m.selectedFinding
	if scan.Categorize(f) != scan.CategoryMisconfiguration {
		return nil
	}
	rule, a := misconfigFixAvailability(f, true)
	if rule.AVDID == "" || !a.Enabled() {
		return nil
	}
	m.previewSeq++
	seq, target := m.previewSeq, m.targetPath
	scannedAt := m.result.EndTime
	m.changePreview = changePreview{Seq: seq, Target: target, Finding: f}
	return func() tea.Msg {
		return ChangePreviewMsg{Seq: seq, Target: target, Prepared: computeMisconfigFix(target, f, scannedAt)}
	}
}

func (m Model) handleChangePreview(msg ChangePreviewMsg) (tea.Model, tea.Cmd) {
	p := m.changePreview
	if m.state != StateDetails || p.Seq == 0 || msg.Seq != p.Seq || msg.Target != p.Target || msg.Target != m.targetPath ||
		m.selectedFinding == nil || !sameFinding(p.Finding, *m.selectedFinding) {
		return m, nil
	}
	p.Prepared = msg.Prepared
	var cmd tea.Cmd
	var d errDeclined
	switch {
	case msg.Prepared.Err == nil:
		p.State = previewReady
	case errors.As(msg.Prepared.Err, &d) && d.reason == reasonPreviewStale:
		p.State = previewExpired
	case errors.As(msg.Prepared.Err, &d):
		p.State = previewDeclined
	default:
		log.Printf("ERROR [security/misconfig] preview fix: %v", msg.Prepared.Err)
		p.State = previewFailed
		p.Failure = previewFailure(p.Finding.File, msg.Prepared.Err)
		cmd = m.footer.Error("Could not preview the fix — check logs")
	}
	m.changePreview = p
	m.detailsViewport.SetContent(m.buildDetailsContent())
	return m, cmd
}

func (m Model) previewVerdict(f scan.Finding) shortcut.Availability {
	p := m.changePreview
	if m.state != StateDetails || p.Seq == 0 || !sameFinding(p.Finding, f) {
		return shortcut.Availability{}
	}
	switch p.State {
	case previewExpired:
		return shortcut.Unavailable(reasonPreviewStale)
	case previewDeclined:
		var d errDeclined
		if errors.As(p.Prepared.Err, &d) {
			return shortcut.Unavailable(d.reason)
		}
	}
	return shortcut.Availability{}
}

func (m Model) fixStatus(f scan.Finding) fixStatus {
	st := fixStatusOf(f, m.targetOnDisk())
	if st.State == fixBuiltIn {
		if a := m.previewVerdict(f); !a.Enabled() {
			st.State, st.Reason = fixBuiltInDeclined, a.Reason
		}
	}
	return st
}

func (m Model) previewPendingStatus() (sharedcomponents.Status, bool) {
	if m.state == StateDetails && m.changePreview.Seq != 0 && m.changePreview.State == previewPending {
		return sharedcomponents.Status{Text: "Preparing the change preview...", Activity: true}, true
	}
	return sharedcomponents.Status{}, false
}

func (m Model) detailsChange(f scan.Finding, t detailsText) []string {
	const label = "Change: "
	if scan.Categorize(f) == scan.CategoryVulnerability {
		if delta, ok := versionDelta(f); ok {
			return t.field(label, delta, t.text)
		}
		return t.field(label, "none: DevDesk cannot write this fix", t.text)
	}
	p := m.changePreview
	if p.Seq == 0 || !sameFinding(p.Finding, f) {
		return t.field(label, "none: DevDesk cannot write this fix", t.text)
	}
	switch p.State {
	case previewPending:
		return t.field(label, "preparing the preview...", t.text)
	case previewExpired:
		return t.field(label, "stale preview: "+f.File+" changed after the scan", t.text)
	case previewFailed:
		return t.field(label, "preview failed: "+p.Failure, t.text)
	case previewDeclined:
		return t.field(label, "none: DevDesk cannot write this fix", t.text)
	}
	lines := t.field(label, p.Prepared.File.File, t.text)
	rows := p.Prepared.Lines
	for i, row := range rows {
		if i == maxChangeRows {
